import sys,struct; sys.path.insert(0,'/workspace/tmp')
from probe import *
lib=build()
def case(**kw):
    c=dict(primitive='allreduce',mode=3,root=0,segments=4,words=1,capacity=8,start=0,events=[],trace=0)
    c.update(kw); return c
def D(r,p,v=[1]): return {'op':'data','rank':r,'p':p,'values':v}

print("== wrapped PSNs: start = 2^24-2, K=4 ==")
evs=[D(r,p) for p in range(4) for r in range(4)]
res=run(case(events=evs,start=(1<<24)-2,trace=40),lib); show(res)
for t in res['trace'][:6]:
    f=bytes.fromhex(t['hex']); apsn=struct.unpack('!I',f[50:54])[0]
    print('   rank=%d op=%d psn=%d'%(t['rank'],f[42],apsn&0xffffff))

print("== invariant: 18 == 22+23+24+25 and 18+19+26+27 == ingress frames ==")
import itertools, random
random.seed(3)
for trial in range(40):
    evs=[]
    for i in range(25):
        c=random.random()
        r=random.randrange(4)
        if c<0.5: evs.append(D(r,random.randrange(4),[random.randrange(100)]))
        elif c<0.65: evs.append({'op':'ack','rank':r,'upto':random.randrange(0,6)})
        elif c<0.75: evs.append({'op':'flush'})
        elif c<0.85: evs.append({'op':'retry','rank':r})
        elif c<0.92: evs.append({'op':'budget','n':random.randrange(0,3)})
        else: evs.append({'op':'wire','rank':r,'hex':'00'*random.randrange(0,40)})
    res=run(case(events=evs,segments=4,capacity=3,mode=random.choice([2,3])),lib)
    st=res['state']
    assert st[18]==st[22]+st[23]+st[24]+st[25], (st,)
    assert st[30]==0, st
    assert st[31]==0, st
    # total ingress classification
    n_in=sum(1 for e in evs if e['op'] in ('data','ack','wire'))
    assert st[18]+st[19]+st[26]+st[27]==n_in, (st,n_in)
print('   invariants hold over 40 random traces')
EOF
